import{c as e,Q as s,j as p,m as n}from"./chunks/framework.DOi4mjdC.js";const w=JSON.parse('{"title":"如何使用workspace","description":"","frontmatter":{},"headers":[{"level":1,"title":"如何使用workspace","slug":"如何使用workspace"}],"relativePath":"guide/编程指南/附录/常用操作/如何使用workspace.md","filePath":"guide/编程指南/附录/常用操作/如何使用workspace.md"}'),c={name:"guide/编程指南/附录/常用操作/如何使用workspace.md"};function r(l,a,o,t,i,k){return s(),p("div",null,[...a[0]||(a[0]=[n(`<h1 id="如何使用workspace" tabindex="-1">如何使用workspace <a class="header-anchor" href="#如何使用workspace" aria-label="Permalink to &quot;如何使用workspace&quot;">​</a></h1><p>workspace是设备侧Global Memory上的一块内存。workspace内存分为两部分：系统workspace和用户workspace。</p><ul><li><p>系统workspace：Ascend C API需要预留的workspace内存</p><p>API在计算过程需要一些workspace内存作为缓存，因此算子需要为API预留workspace内存，预留内存大小通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetLibApiWorkSpaceSize.md" target="_blank" rel="noreferrer">GetLibApiWorkSpaceSize</a>接口获取。</p></li><li><p>用户workspace：算子实现使用到的workspace内存</p><p>算子内部需要通过额外的device内存进行数据交换或者缓存的时候才需要分配，根据实际情况自行分配。使用场景如下：</p><ul><li>需要使用Unified Buffer和L1 Buffer上的空间且空间不够用时，可以将数据暂存至workspace上。</li><li>调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SyncAll.md" target="_blank" rel="noreferrer">SyncAll</a>等API接口时，需要workspace作为入参。</li><li>其他需要使用Global Memory上内存空间的场景。</li></ul></li></ul><p>不同开发方式下，具体的使用方法如下：</p><ul><li><p>工程化算子开发方式</p><p>在tiling函数中先通过GetWorkspaceSizes接口获取workspace大小的存放位置，再设置workspace的大小，框架侧会为其申请对应大小的设备侧Global Memory，在对应的算子kernel侧实现时可以使用这块workspace内存。在使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul-Kernel%E4%BE%A7%E6%8E%A5%E5%8F%A3.md" target="_blank" rel="noreferrer">Matmul Kernel侧接口</a>等需要系统workspace的高阶API时，设置的workspace空间大小为系统workspace和用户workspace之和。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 用户自定义的tiling函数</span></span>
<span class="line"><span>static ge::graphStatus TilingFunc(gert::TilingContext* context)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AddApiTiling tiling;</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    size_t usrSize = 256; // 设置用户需要使用的workspace大小为256字节。</span></span>
<span class="line"><span>    // 如需要使用系统workspace需要调用GetLibApiWorkSpaceSize获取系统workspace的大小。</span></span>
<span class="line"><span>    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>    uint32_t sysWorkspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();</span></span>
<span class="line"><span>    size_t *currentWorkspace = context-&gt;GetWorkspaceSizes(1); // 通过框架获取workspace的指针，GetWorkspaceSizes入参为所需workspace的块数。当前限制使用一块。</span></span>
<span class="line"><span>    currentWorkspace[0] = usrSize + sysWorkspaceSize; // 设置总的workspace的数值大小，总的workspace空间由框架来申请并管理。</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在device侧kernel入口处的workspace为用户的workspace指针：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 用户写的Kernel函数，核函数必须包括GM_ADDR workspace入参，位置需要放在tiling之前</span></span>
<span class="line"><span>extern &quot;C&quot; __global__ __aicore__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR workspace, GM_ADDR tiling)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Kernel直调算子开发场景</p><p>需要使用workspace空间时，建议开启编译选项<a href="./../基于样例工程完成Kernel直调.html#li1103101565014">HAVE_WORKSPACE</a>。host侧开发者仍需要自行申请workspace的空间，并传入。在使用Matmul Kernel侧接口等需要系统workspace的高阶API时，设置的workspace空间大小为系统workspace和用户workspace之和。系统workspace大小可以通过PlatformAscendCManager的GetLibApiWorkSpaceSize接口获取。开启<a href="./../基于样例工程完成Kernel直调.html#li1103101565014">HAVE_WORKSPACE</a>后，开发者在kernel侧入参处获取的workspace为偏移了系统workspace后的用户workspace。</p></li></ul>`,5)])])}const _=e(c,[["render",r]]);export{w as __pageData,_ as default};
